import express from 'express';import dotenv from 'dotenv';dotenv.config();const app=express();app.use(express.json());const PORT=Number(process.env.GAMELAB_ORCHESTRATOR_PORT||7195);app.get('/health',(_q,r)=>r.json({ok:true,service:'gamelab-orchestrator',vm:process.env.GAMELAB_VM_NAME||'gamelab-cpu'}));app.post('/vm/plan',(q,r)=>r.json({ok:true,dryRun:true,cmd:`lxc init ${process.env.GAMELAB_IMAGE||'ubuntu:24.04'} ${process.env.GAMELAB_VM_NAME||'gamelab-cpu'} --vm --config limits.cpu=${process.env.GAMELAB_CPU||12} --config limits.memory=${process.env.GAMELAB_MEMORY||'24GiB'} -s ${process.env.GAMELAB_STORAGE||'local-dir'}`}));app.listen(PORT,'0.0.0.0',()=>console.log('gamelab orchestrator',PORT));